UPDATE `locales_quest` SET `offerrewardtext_loc4` = '<塞勒斯从你的手中一把拿过烈焰精华。>$B$B就是它!$B$B拿着你的奖励，然後走开。马上从我眼前消失!$B$B' WHERE `entry` = 4024 AND `offerrewardtext_loc4` = '<塞勒斯从你的手中一把拿过烈焰精华。>$B$B就是它!$B$B拿着你的奖励，然後走开。马上从我眼前消失!$B';
