UPDATE `locales_page_text` SET `text_loc4` = '<HTML><BODY><H1 align="center">第一章:北部水晶塔</H1><BR/><BR/><IMG src="Interface\\Pictures\\11482_crystals_mini_north" align="left"/><P align="right">The Northern<BR/>Pylon accepts<BR/>yellow, red,<BR/>and green<BR/>crystals.</P><BR/><BR/><BR/><BR/><P align="left">The Pylon focuses on the energy that can be created using yellow crystals as the main source of power.</P></BODY></HTML>' WHERE `entry` = 1511 AND `text_loc4` = '<HTML><BR/> <BODY><BR/> <H1 align="center"><BR/> 第一章：北部水晶塔<BR/> </H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src="InterfacePictures11482_crystals_mini_north"/><BR/> <P align="right">北部水晶塔<BR/><BR/> 可以接受<BR/><BR/> 黄色、红色<BR/><BR/> 以及绿色的<BR/><BR/> 水晶。</P><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <P align="left">水晶塔依靠黄色水晶作为主要能源来制造特殊的物品。</P><BR/> </BODY><BR/> </HTML>';
