UPDATE `locales_page_text` SET `text_loc4` = '<HTML><BODY><H1 align="center">军阶概述</H1><BR/><BR/><IMG src="Interface\\PvPRankBadges\\PvPRankAlliance" align="left"/><BR/><P align="right">What follows are</P><P align="right">the military ranks</P><P align="right">of the Alliance,</P><P align="right">proceeded by such</P><P align="right">information as is</P><P align="right">known for the races</P><P align="right">of the Horde. Each</P><P align="right">is presented in two</P><P align="right">sections, the officers and then the enlisted, with the ranks of each listed in descending order from highest to lowest. Long live the Alliance!</P></BODY></HTML>' WHERE `entry` = 2654 AND `text_loc4` = '<HTML><BR/> <BODY><BR/> <H1 align="center">军阶概述</H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src="InterfacePvPRankBadgesPvPRankAlliance" align="left"/><BR/> <BR/><BR/> <P align="right">以下是</P><BR/> <P align="right">联盟的</P><BR/> <P align="right">军阶概述，</P><BR/> <P align="right">其中包括</P><BR/> <P align="right">部落</P><BR/> <P align="right">种族熟知的</P><BR/> <P align="right">信息。每一部分都</P><BR/> <P align="right">包含两个</P><BR/> <P align="right">章节，军官和士兵的军阶，都是按照由高到低的顺序排列的。联盟万岁!</P><BR/> </BODY><BR/> <';
